window.EXTRA=Object.assign(window.EXTRA||{},{
indrev:[["Inventions","Key inventions included the spinning jenny (about 1764), the power loom and the railway locomotive. Cotton textiles drove early growth, and Manchester became a leading factory city."]],
atom:[["Subatomic particles","Protons and neutrons are made of smaller particles called quarks. Isotopes are atoms of one element with different numbers of neutrons, and some of them are radioactive."]],
grav:[["Orbits and escape","An object orbits when its sideways speed balances gravity’s pull; low Earth orbit needs about 7.8 km/s. Escaping Earth’s gravity altogether takes about 11.2 km/s."]],
cell:[["Cell division","Mitosis makes two identical cells for growth and repair, while meiosis makes sex cells with half the usual number of chromosomes."]],
light:[["Color and vision","The retina has rods for dim light and cones for color, and most people have three kinds of cones. Objects look colored because they reflect some wavelengths and absorb others."]],
renais:[["Science and patrons","Copernicus proposed a Sun-centered model in 1543, and Galileo’s telescope observations later supported it. Wealthy city-states such as Florence, under the Medici family, funded artists and scholars."]],
maya:[["Collapse and survival","Many southern lowland cities were abandoned between about 800 and 900 CE, probably because of drought, warfare and political change. The Maya did not vanish, and northern cities such as Chichén Itzá flourished afterward."]],
silk:[["Goods and ideas","Buddhism spread from India into China along these routes, and paper and gunpowder eventually reached the West. Cities such as Samarkand and Kashgar grew rich as trading hubs."]],
everest:[["Climbing","At the summit, air pressure is roughly one third of that at sea level, and many climbers use bottled oxygen. The peak is called Sagarmatha in Nepali and Chomolungma in Tibetan."]],
sahara:[["Peoples and trade","Nomadic peoples such as the Tuareg have crossed the desert for centuries, and camel caravans carried salt, gold and other goods between West Africa and the Mediterranean."]],
pacific:[["Islands and navigators","Polynesian navigators settled islands across the Pacific using stars, ocean swells and birds, reaching Hawaii and Rapa Nui. Magellan named the ocean, meaning peaceful, in 1520."]],
nile:[["Delta and dams","The Nile Delta is a fertile fan of farmland that holds much of Egypt’s population. Ethiopia’s Grand Ethiopian Renaissance Dam on the Blue Nile, which began filling in 2020, has made water sharing a major regional issue."]],
antarc:[["Science","Researchers drill ice cores that trap air bubbles going back about 800,000 years, recording past climates. The South Pole was first reached by Roald Amundsen’s team in December 1911."]],
flight:[["How wings work","A wing deflects air downward and creates lower pressure above it than below, producing lift. Engines supply thrust to overcome drag."]],
gps:[["Beyond navigation","Power grids and financial systems use GPS time signals to stay synchronized. Other satellite systems include Russia’s GLONASS, Europe’s Galileo and China’s BeiDou."]],
quantum:[["Quantum computing","Quantum computers use superposition and entanglement to attack certain problems, such as simulating molecules, that are hard for classical machines. Today’s devices are still small and error-prone."]],
relat:[["Mass and energy","The equation E = mc² shows that a small amount of mass corresponds to a very large amount of energy. It underlies both nuclear power and the way stars shine."]],
immune:[["Allergies and autoimmunity","Allergies occur when the immune system overreacts to harmless substances such as pollen. In autoimmune diseases it attacks the body’s own tissues."]],
sound:[["Music and hearing","Musical notes are sounds with regular frequencies, and an octave doubles the frequency. The ear’s cochlea converts vibrations into nerve signals."]],
magnet:[["Compasses","A compass needle aligns with Earth’s magnetic field, and Chinese navigators were using lodestone compasses by about the 11th century. Earth’s magnetic poles drift and have reversed many times over geologic history."]]});

;
