/* data/extra-sections4.js */
window.EXTRA=Object.assign(window.EXTRA||{},{
print:[["Spread of printing","By 1500 presses were operating in more than 200 European towns. Printed pamphlets helped spread Martin Luther’s ideas, and the first newspapers appeared in the early 1600s."]],
eco:[["Succession","After a fire or volcanic eruption, pioneer species such as lichens and grasses move in first, and the community gradually shifts toward a stable forest in a process called ecological succession."]],
acid:[["In the body","Stomach acid has a pH of roughly 1.5 to 3.5 and helps digest food and kill germs. Buffers keep blood at a nearly constant pH of about 7.4."]],
aztec:[["Farming and religion","The Aztecs built floating gardens called chinampas that produced several crops a year. Their religion centered on gods such as Huitzilopochtli, and the Templo Mayor stood at the heart of Tenochtitlan."]],
ottoman:[["Society","Under the millet system, religious communities such as Christians and Jews ran many of their own affairs. The janissaries, an elite infantry corps, were recruited largely through the devshirme system."]],
china:[["Dynasties and voyages","The Tang dynasty (618 to 907) is often seen as a golden age of poetry and Silk Road trade. Under the Ming, Admiral Zheng He led treasure fleets as far as East Africa between 1405 and 1433."]],
explor:[["Consequences","Contact brought crops such as potatoes, maize and tomatoes to the Old World, and horses and wheat to the Americas. It also brought epidemic disease, conquest and the Atlantic slave trade."]],
usrev:[["Causes","Colonists objected to taxes imposed by Britain without representation in Parliament, such as the Stamp Act of 1765. Fighting began in April 1775 at Lexington and Concord."]],
alps:[["Energy and tunnels","Alpine rivers feed hydropower plants that supply much of Switzerland’s and Austria’s electricity. The Gotthard Base Tunnel, opened in 2016, is the world’s longest railway tunnel at about 57 km."]],
andes:[["Life at altitude","Highland peoples such as the Quechua have adapted to thin air, and llamas and alpacas have been herded there for thousands of years. The Altiplano plateau holds Lake Titicaca and the Uyuni salt flat."]],
canyon:[["Formation","The Colorado River carved the canyon as the Colorado Plateau slowly rose. Scientists still debate when the carving began, with estimates ranging from about 5 million to 70 million years ago."]],
sea:[["History","Angkor in Cambodia was the capital of the Khmer Empire, and its temple Angkor Wat dates to the early 1100s. Most of the region was colonized by European powers or the United States, while Thailand was never colonized."]],
iceland:[["Geysers and glaciers","The word geyser comes from Geysir, a hot spring in Iceland. About a tenth of the country is covered by glaciers, including Vatnajökull, one of Europe’s largest ice caps."]],
laser:[["Medicine and industry","LASIK eye surgery reshapes the cornea with a laser, and industrial lasers can cut steel. The LIGO observatory uses lasers to measure changes in distance smaller than a proton."]],
chip:[["Why silicon","Silicon is abundant, being a main ingredient of sand, and it can be purified to extreme levels and mixed with other elements to control how it conducts. Fabs use ultraviolet light to print circuit patterns onto wafers."]],
radio:[["Broadcasting","AM radio varies the strength of a wave, while FM varies its frequency and sounds clearer. Commercial broadcasting began in 1920 with stations such as KDKA in Pittsburgh."]],
steam:[["Steam today","Charles Parsons invented the modern steam turbine in 1884, and such turbines spin generators at power plants. Whether the heat comes from coal, gas or a nuclear reactor, the steam cycle is much the same."]],
scope:[["Radio and space","Radio telescopes such as FAST in China collect radio waves from space. The James Webb telescope sits about 1.5 million km from Earth at a point called L2."]],
robot:[["Types","Robots range from fixed factory arms to wheeled and legged machines, drones and humanoids. Many combine sensors, motors and software that lets them react to their surroundings."]],
crypto:[["Hashes and signatures","A hash function turns data into a short, fixed-length fingerprint, so changing even one character changes the result. Digital signatures use key pairs to prove that a message came from its sender."]]});

;
