/* data/articles-batch5.js */
window.MORE=(window.MORE||[]).concat([
{id:"tides",t:"The Tides",c:"Science",i:"🌊",p:[["Cause","The Moon’s gravity pulls on the oceans and raises two bulges of water. As Earth turns through them, most coasts see two high tides roughly every 24 hours and 50 minutes."],["Spring and neap","Spring tides, with the largest range, occur near new and full moon when the Sun, Earth and Moon line up. Neap tides, with the smallest range, occur near the quarter moons."],["Extremes","The Bay of Fundy in Canada has some of the highest tides in the world, with a range of up to about 16 m."]],r:["grav","pacific"]},
{id:"microbe",t:"Bacteria and Viruses",c:"Science",i:"🦠",p:[["Bacteria","Bacteria are single-celled organisms. Most are harmless or helpful, such as those that aid digestion, though some cause disease. Antibiotics treat bacterial infections."],["Viruses","Viruses are far smaller and can reproduce only inside host cells. Antibiotics do not work on them, but vaccines and antiviral drugs can."],["Discovery","Antonie van Leeuwenhoek saw bacteria through a microscope in the 1670s, and Louis Pasteur and Robert Koch linked germs to disease in the 1800s."]],r:["immune","cell"]},
{id:"moon",t:"The Moon",c:"Science",i:"🌙",p:[["Facts","The Moon is about 384,400 km away and roughly a quarter of Earth’s width. Tidal locking means it always shows the same face to us."],["Phases","The Moon’s phases follow the changing angle between the Sun, Earth and Moon, and the cycle takes about 29.5 days."],["Exploration","Twelve people walked on the Moon during the Apollo missions of 1969 to 1972. China’s Chang’e 4 made the first landing on the far side in 2019."]],r:["solar","space"]},
{id:"viking",t:"The Viking Age",c:"History",i:"⛵",p:[["Raids","The Viking Age is usually dated from the raid on Lindisfarne in 793 to about 1066. Norse raiders, traders and settlers came from Scandinavia."],["Voyages","Leif Erikson reached North America around the year 1000, and L’Anse aux Meadows in Newfoundland is a confirmed Norse site."],["Society","Longships let Norse seafarers travel across seas and up rivers, and assemblies called things, such as Iceland’s Althing, settled disputes."]],r:["iceland","explor"]},
{id:"reform",t:"The Reformation",c:"History",i:"✝️",p:[["Beginning","In 1517 Martin Luther published his Ninety-five Theses, criticizing the sale of indulgences. The movement soon challenged the authority of the Catholic Church."],["Spread","The printing press carried reformers’ pamphlets across Europe, and new Protestant churches followed, including Lutheran and Reformed traditions."],["Consequences","Religious wars shook Europe until the Peace of Westphalia in 1648."]],r:["print","renais"]},
{id:"mesop",t:"Ancient Mesopotamia",c:"History",i:"🏛️",p:[["The land between rivers","Mesopotamia lay between the Tigris and Euphrates in what is now Iraq. Sumerian cities such as Uruk had emerged by about 3500 BCE."],["Writing","Cuneiform, written by pressing a reed into clay, appeared around 3300 BCE and was used for accounts, letters and literature such as the Epic of Gilgamesh."],["Law","The Code of Hammurabi, from about 1754 BCE, is one of the earliest surviving written law codes."]],r:["egypt","nile"]},
{id:"madag",t:"Madagascar",c:"Geography",i:"🦎",p:[["Island","Madagascar is the fourth largest island in the world, lying off southeastern Africa. It split from the Indian landmass roughly 88 million years ago."],["Wildlife","Around 90% of its plants and animals are found nowhere else, including more than 100 species of lemur."],["People","Austronesian settlers from Southeast Asia arrived roughly 1,500 or more years ago, and the Malagasy language is related to languages of Borneo."]],r:["evo","sea"]},
{id:"rift",t:"The Great Rift Valley",c:"Geography",i:"🏜️",p:[["Formation","The East African Rift is where the African plate is slowly splitting into two plates. It stretches for thousands of kilometers."],["Landscape","Rift activity has produced volcanoes, deep lakes such as Tanganyika and low, hot basins such as the Afar region of Ethiopia."],["Human origins","Fossils of early humans have been found there, including the 3.2-million-year-old skeleton known as Lucy, discovered in Ethiopia in 1974."]],r:["tect","sahara"]},
{id:"mekong",t:"The Mekong",c:"Geography",i:"🛶",p:[["Course","The Mekong runs about 4,350 km from the Tibetan Plateau through China, Myanmar, Laos, Thailand, Cambodia and Vietnam."],["Tonlé Sap","In Cambodia, the Tonlé Sap river reverses direction each year when the Mekong floods, swelling the Tonlé Sap lake to several times its dry-season size."],["Delta","Vietnam’s Mekong Delta is one of the world’s great rice-growing regions and supports tens of millions of people."]],r:["sea","nile"]},
{id:"camera",t:"The Camera",c:"Technology",i:"📷",p:[["Early photography","The camera obscura projected images long before photography. Nicéphore Niépce made the earliest surviving permanent photograph around 1826."],["Film","George Eastman’s Kodak camera of 1888 made photography simple enough for ordinary people."],["Digital","Steven Sasson, an engineer at Kodak, built the first digital camera in 1975, and smartphones later put cameras in nearly every pocket."]],r:["light","phone"]},
{id:"ev",t:"Electric Vehicles",c:"Technology",i:"🔌",p:[["History","Electric cars were built in the 1800s and were popular around 1900 before gasoline cars became cheaper and easier to refuel."],["Batteries","Modern electric vehicles run on lithium-ion battery packs, and regenerative braking recovers energy that would otherwise be lost as heat."],["Grid","Charging adds demand to the power grid, and vehicles charged at off-peak times can help balance supply and demand."]],r:["battery","renew"]},
{id:"wind",t:"Wind Power",c:"Technology",i:"🌬️",p:[["Turbines","A wind turbine turns the kinetic energy of moving air into electricity. The blades of the largest offshore turbines are more than 100 m long."],["Growth","Wind supplies several percent of the world’s electricity, and its output rises and falls with the weather."],["Around the world","China, the United States, Germany, India and Spain have the most wind power."]],r:["renew","elec"]}]);
