window.MORE=(window.MORE||[]).concat([
{id:"gmyth",t:"Greek Mythology",c:"Arts and Literature",i:"⚡",p:[["The gods","The principal Greek gods, led by Zeus, were said to live on Mount Olympus. They included Hera, Poseidon, Athena, Apollo, Artemis, Ares, Aphrodite, Hephaestus, Hermes and Demeter."],["Heroes","Heroes such as Heracles, Perseus and Odysseus faced monsters and trials, and myths explained natural events and human fate."],["Legacy","Roman writers adopted the gods under new names, and words such as echo, panic and narcissism, along with planet and constellation names, come from these myths."]],r:["homer","greece"]},
{id:"opera",t:"Opera",c:"Arts and Literature",i:"🎤",p:[["Beginnings","Opera began in Florence around 1600, and Claudio Monteverdi’s L’Orfeo of 1607 is one of the earliest great operas still performed."],["Composers","Mozart’s The Magic Flute (1791), Verdi’s La traviata (1853) and Puccini’s Tosca (1900) are among the most beloved works."],["Voices","Singers are classed by voice type, such as soprano, tenor and bass, and perform to the text of a libretto with an orchestra in the pit."]],r:["musicw","theatre"]},
{id:"haikuart",t:"Haiku and Japanese Poetry",c:"Arts and Literature",i:"🌸",p:[["Form","A haiku is a short poem, traditionally in three lines of five, seven and five sound units, and it often includes a word that points to a season."],["Bashō","Matsuo Bashō (1644 to 1694) is the most famous haiku master, and his travel diary The Narrow Road to the Deep North mixes prose and verse."],["Spread","Haiku has inspired poets worldwide, who write them in many languages and often loosen the strict sound count."]],r:["china","novel"]},
{id:"teeth",t:"Teeth and Oral Health",c:"Health and the Body",i:"🦷",p:[["Structure","Adults normally have 32 permanent teeth. Enamel, the outer layer, is the hardest substance in the body."],["Decay","Bacteria in plaque turn sugars into acids that wear away enamel and cause cavities. Fluoride helps strengthen enamel."],["Care","Brushing twice a day, cleaning between teeth and regular dental checkups prevent most dental problems."]],r:["bones","nutri"]},
{id:"water",t:"Water and the Body",c:"Health and the Body",i:"🚰",p:[["How much","Water makes up roughly 60% of an adult’s body weight. It carries nutrients, helps regulate temperature and removes waste."],["Balance","The kidneys keep the body’s water and salt in balance, and thirst prompts you to drink when levels fall."],["Needs","How much a person needs depends on age, activity and climate, and food supplies part of it."]],r:["heart","wcycle"]},
{id:"flu",t:"Colds and Influenza",c:"Health and the Body",i:"🤧",p:[["Causes","Colds are caused by many viruses, most often rhinoviruses, while influenza is caused by influenza viruses. Antibiotics do not work against viruses."],["1918 pandemic","The 1918 influenza pandemic is estimated to have killed around 50 million people worldwide."],["Prevention","Handwashing, staying home when sick and yearly flu vaccines reduce spread, and the vaccine is updated as the virus changes."]],r:["microbe","vacc"]},
{id:"zero",t:"Numbers and Zero",c:"Mathematics",i:"0️⃣",p:[["Counting","People used tally marks and number words long before writing. Babylonians used a base-60 system, and the Romans used letters for numbers."],["Zero","The Indian mathematician Brahmagupta set out rules for arithmetic with zero in 628 CE, and zero as a placeholder appeared earlier in several cultures."],["Spread","The Hindu–Arabic numerals reached Europe through works such as Fibonacci’s Liber Abaci of 1202."]],r:["mesop","silk"]},
{id:"euclid",t:"Euclid and Geometry",c:"Mathematics",i:"📐",p:[["Elements","Euclid wrote the Elements around 300 BCE, building geometry from a few simple assumptions and proving each result step by step."],["Pythagoras","The Pythagorean theorem says that in a right triangle the square of the longest side equals the sum of the squares of the other two. Babylonians knew the idea long before Pythagoras."],["Influence","The Elements was a standard textbook for over two thousand years and shaped the idea of mathematical proof."]],r:["greece","mesop"]},
{id:"prob",t:"Probability",c:"Mathematics",i:"🎲",p:[["Beginnings","Blaise Pascal and Pierre de Fermat exchanged letters in 1654 about gambling problems, helping to found probability theory."],["Idea","Probability measures how likely an event is on a scale from 0, which means impossible, to 1, which means certain."],["Uses","Insurance, medicine, weather forecasts and machine learning all rely on probability and statistics."]],r:["ai","newton"]},
{id:"prime",t:"Prime Numbers",c:"Mathematics",i:"🔢",p:[["Definition","A prime number is greater than 1 and divisible only by 1 and itself. The first primes are 2, 3, 5, 7 and 11."],["Infinitely many","Euclid proved around 300 BCE that there are infinitely many primes."],["In practice","Multiplying huge primes is easy but factoring the product is hard, a fact that protects much online encryption."]],r:["crypto","euclid"]},
{id:"socr",t:"Socrates, Plato and Aristotle",c:"Religion and Philosophy",i:"🏛️",p:[["Socrates","Socrates (470 to 399 BCE) taught in Athens by asking questions and was sentenced to death for impiety and corrupting the young."],["Plato","His student Plato founded the Academy in Athens and wrote dialogues, including the Republic, in which Socrates is the main speaker."],["Aristotle","Aristotle studied under Plato, tutored Alexander the Great and wrote on logic, ethics, politics and biology."]],r:["greece","renais"]},
{id:"buddh",t:"Buddhism",c:"Religion and Philosophy",i:"☸️",p:[["The Buddha","Siddhartha Gautama lived in northern India, probably in the 5th century BCE, and became known as the Buddha, or the awakened one."],["Teachings","The Four Noble Truths say that life involves suffering, that suffering has a cause, that it can end and that the Eightfold Path leads to its end."],["Spread","Buddhism spread across Asia along trade routes, and today its main traditions include Theravada, Mahayana and Vajrayana."]],r:["silk","china"]},
{id:"confu",t:"Confucius",c:"Religion and Philosophy",i:"📖",p:[["Life","Confucius (551 to 479 BCE) was a teacher and thinker in the state of Lu, in what is now China."],["Ideas","He stressed ethics, family loyalty, education and good government, summed up in the idea of ren, or humaneness."],["Analects","His sayings were collected by his followers in the Analects, and Confucian ideas shaped Chinese and East Asian society for over two thousand years."]],r:["china","socr"]},
{id:"relig",t:"World Religions",c:"Religion and Philosophy",i:"🕊️",p:[["Largest faiths","Christianity and Islam are the two largest religions, each followed by roughly two billion people, followed by Hinduism, with over a billion, and Buddhism."],["Shared themes","Many traditions have sacred texts, rituals, moral teachings and ideas about meaning, community and what lies beyond death."],["Around the world","About eight in ten people follow a religion, most commonly Christianity, Islam, Hinduism or Buddhism."]],r:["spanph","sulu"]}]);
